export const atlasAdditions = [
  site('ostia','Ostia','Italië · Tibermonding',[12.289,41.755],'roman',100,'Ostia Antica Ostium Portus',
    [[-300,400,'Ostia']],[
      ['4e eeuw v.Chr.','Een versterking aan de monding','Een rechthoekig castrum bewaakte de toegang tot de Tiber en lag bij zoutpannen. De oudste gedateerde muren zijn jonger dan het verhaal dat koning Ancus Marcius de stad zou hebben gesticht.'],
      ['1e–2e eeuw n.Chr.','Twee havens voor Rome','Claudius liet ten noorden van Ostia bij Portus een zeehaven aanleggen. Trajanus voegde een binnenbekken toe. In Ostia konden handelaren, dragers en schippers goederen opslaan en overslaan voordat kleinere schepen ze naar Rome brachten.'],
      ['Late oudheid','De overslag verschuift','Portus won aan gewicht. De aanwezigheid van woningen en kerken in Ostia maakt duidelijk dat een verandering in handelsverkeer niet hetzelfde is als het onmiddellijke einde van de bewoning.']],
    'Hoe veranderde een fort aan een riviermonding in een schakel van Romes bevoorrading?', ['Waarom kon Portus de functie van Ostia veranderen?', 'De zeebekkens verplaatsten een deel van de overslag. De rivier, pakhuizen en kleinere vaartuigen bleven nodig voor vervoer naar Rome.'],
    [ref('Parco archeologico di Ostia antica','General panels','Ancient Ostia: history and urban development','https://ostiaantica.cultura.gov.it/en/educational-panels-and-maps/general-panels/')],['rome-annona']),
  site('pompeii','Pompeï','Italië · Campanië',[14.487,40.751],'roman',79,'Pompeii Pompei Vesuvius',
    [[-80,79,'Pompeii']],[
      ['1e eeuw v.Chr.','Een stad in Romeins Italië','In de Romeinse kolonie lagen werkplaatsen, winkels, huizen en heiligdommen dicht bij elkaar. Het stratenplan en de gebouwen bevatten sporen van bouwfasen van vóór de Romeinse kolonisatie.'],
      ['79 n.Chr.','Een uitbarsting onderbreekt het stadsleven','Vulkanisch materiaal bedekte gebouwen en straten. Voorwerpen op hun vindplaats maken activiteiten in afzonderlijke huizen zichtbaar. Vlucht, instorting en latere opgravingen bepaalden mee wat bewaard bleef.'],
      ['Vanaf de 18e eeuw','Van vindplaats naar opgraving','Bij de vroege opgravingen trokken schilderingen en kostbare objecten veel aandacht. Huidige onderzoekers moeten rekening houden met wat oudere opgravers verzamelden, weggooiden of onvolledig beschreven.']],
    'Wat maakt een huis in Pompeï bruikbaar als historische bron, en waarom is het geen ongefilterd beeld van één dag?', ['Waarom geeft een voorwerp in een kamer niet vanzelf het gewone gebruik van die kamer weer?', 'Bewoners verplaatsten bezittingen, gebouwen stortten in en eerdere opgravers selecteerden vondsten. De vindcontext en bouwfase bepalen welke uitleg houdbaar is.'],
    [wh(829,'Archaeological Areas of Pompei, Herculaneum and Torre Annunziata')],['r2-vesuvius-brieven']),
  site('napels','Napels','Italië · Baai van Napels',[14.258,40.851],'greek',-450,'Neapolis Napoli Napels Parthenope',
    [[-450,350,'Neapolis'],[1300,1600,'Napoli']],[
      ['5e eeuw v.Chr.','Neapolis aan de baai','Griekse kolonisten ontwikkelden Neapolis bij een oudere nederzetting. Lange straten met dwarsverbindingen verdeelden het stedelijke terrein. Delen van dit patroon zijn in latere bebouwing herkenbaar.'],
      ['13e–14e eeuw','Het hof van Anjou','Met Napels als vorstelijke residentie kregen burchten en religieuze stichtingen nieuwe functies. Castel Nuovo aan de haven drukte zowel de middelen van de dynastie als de betekenis van de toegang over zee uit.']],
    'Bekijk hoe een antiek stratenpatroon en een middeleeuwse residentie verschillende vormen van macht zichtbaar maken.', ['Wat kan een oud straattracé beter aantonen dan een onafgebroken bestuursvorm?', 'Percelen en doorgangen sturen latere bouw. De Angevijnse burcht had een andere opdrachtgever en functie dan het Griekse stratenplan.'],
    [wh(726,'Historic Centre of Naples')]),
  site('capua','Capua','Italië · Santa Maria Capua Vetere',[14.249,41.085],'roman',-73,'Capua vetus Spartacus Campania Santa Maria Capua Vetere',
    [[-200,400,'Capua']],[
      ['73 v.Chr.','Een opstand bij een gladiatorenschool','Spartacus en andere gladiatoren ontkwamen uit een school in Capua. De latere verhalen over hun uitbraak dateren van na de gebeurtenissen en geven vooral de kijk van auteurs uit de Romeinse wereld.'],
      ['1e–2e eeuw n.Chr.','Een arena voor een Romeinse stad','Het bewaarde amfitheater werd pas eeuwen na de opstand gebouwd. De galerijen en dienstruimten maken de organisatie van spelen tastbaar. Ze leveren geen ooggetuigenverslag van de ontsnapping.']],
    'Plaats Spartacus en het bewaarde amfitheater elk in hun eigen tijd.', ['Kan het bewaarde amfitheater aanwijzen hoe Spartacus ontsnapte?', 'De bewaarde bouwfase is veel jonger dan 73 v.Chr. Voor de gebeurtenis moet je de literaire overlevering apart onderzoeken.'],
    [ref('Reggia di Caserta','The national archaeological circuit of Ancient Capua','The Archaeological Museum, the Mithraeum and the Amphitheater','https://reggiadicaserta.cultura.gov.it/en/discover-the-complex/the-archaeological-circuit-of-ancient-capua/'),ref('Ploutarchos','Crassus','8–9, ontsnapping bij Capua','https://classics.mit.edu/Plutarch/crassus.html')]),
  site('ravenna','Ravenna','Italië · Adriatische kust',[12.2,44.417],'roman',402,'Ravenna Classe Classis',
    [[402,750,'Ravenna']],[
      ['5e eeuw','Een residentie in het westen','Vanaf 402 verbleef het West-Romeinse hof in Ravenna. Baptisteria en kerken laten zien hoe keizerlijke bescherming, bisschoppelijk gezag en religieuze identiteit samen zichtbaar konden worden in gebouwen.'],
      ['6e eeuw','Goten en Oost-Romeinen','Het grafmonument van Theoderik en de mozaïeken van San Vitale kwamen onder verschillende machthebbers tot stand. De keizerportretten in de kerk presenteren een aanspraak op gezag, zonder te bewijzen dat Justinianus daar zelf poseerde.']],
    'Lees grafmonument, doopkapel en kerk als getuigen van een wisselend hof.', ['Wat leren keizerportretten in San Vitale over macht op afstand?', 'De voorstelling verbindt liturgie en imperiaal gezag in Ravenna. Zij kan die relatie voorstellen zonder een lokaal bezoek van de keizer te documenteren.'],
    [wh(788,'Early Christian Monuments of Ravenna')],['h2-justinianus-recht']),
  site('milaan','Milaan','Italië · Povlakte',[9.184,45.465],'roman',300,'Mediolanum Milano Milan',
    [[-100,450,'Mediolanum'],[1400,1800,'Milano']],[
      ['Romeinse keizertijd','Mensen achter de monumenten','Inscripties vermelden beroepen, verwantschap en publieke functies. Ze brengen andere inwoners van Mediolanum in beeld dan verhalen over veldheren, maar laten vooral wie een duurzaam opschrift kon laten maken aan het woord.'],
      ['Late 3e–4e eeuw','Het keizerlijke hof','Met de komst van het hof kregen het paleis, de stadsmuur en het circus nieuwe betekenis. De uitbreiding toont hoeveel ruimte een mobiele keizerlijke overheid nodig had voor representatie, bescherming en publieke optredens.']],
    'Leg twee soorten bewijs naast elkaar voor het leven in een keizerlijke residentie.', ['Welke historische vraag vraagt méér dan het grondplan van het paleis?', 'Vragen naar de beroepen en families van Milanese inwoners vragen ook inscripties en vondsten uit andere wijken. Het paleis belicht vooral het hof.'],
    [ref('Civico Museo Archeologico di Milano','Sezione romana','Percorso, chiostro interno en Mediolanum','https://www.museoarcheologicomilano.it/scopri-il-museo/percorsi-di-visita/sezione-romana')]),
  site('aquileia','Aquileia','Italië · Noord-Adriatische kust',[13.368,45.769],'roman',-181,'Aquileia Friuli',
    [[-181,450,'Aquileia'],[1000,1300,'Aquileia']],[
      ['181 v.Chr.','Een Romeinse kolonie','De stichting van een kolonie veranderde de Romeinse aanwezigheid aan de noordelijke Adriatische Zee. De latere rivierhaven koppelde het achterland aan scheepvaart; de ligging van pakhuizen vult het geschreven stichtingsbericht aan.'],
      ['4e eeuw en later','Een bisschopsstad','De christelijke gemeenschap liet monumentale mozaïekvloeren leggen. De basiliek werd herhaaldelijk verbouwd. De plundering van 452 betekende een breuk, maar verklaart niet alle latere verandering in de kerk en haar omgeving.']],
    'Volg de verschuiving van kolonisatie en havenverkeer naar bisschoppelijke instellingen.', ['Waarom dateert men vloer en bovenbouw van de basiliek apart?', 'De kerk werd verschillende keren verbouwd. De mozaïekvloer bewaart een oudere fase dan belangrijke delen van de huidige bovenbouw.'],
    [wh(825,'Archaeological Area and the Patriarchal Basilica of Aquileia')]),
  site('arles','Arles','Frankrijk · Rhône',[4.63,43.676],'roman',330,'Arelate Arles Rhône Provence',
    [[-40,450,'Arelate'],[1000,1400,'Arles']],[
      ['Romeinse keizertijd','Spelen aan de Rhône','Theater, amfitheater en ondergrondse galerijen behoorden tot verschillende bouwprojecten. Ze maakten toeschouwers, handel en bestuurlijke aanwezigheid zichtbaar in een stad met verbindingen naar zee en achterland.'],
      ['4e eeuw','Een laatantieke stad','Thermen en de begraafplaats van de Alyscamps laten andere vormen van stedelijke investering zien. Ze helpen de laatantieke fase afzonderlijk te bestuderen, ook waar oudere gebouwen nog in gebruik waren.'],
      ['11e–12e eeuw','Romaanse bouw','In het middeleeuwse Arles ontstond het complex van Saint-Trophime. Kerk en klooster kregen een plaats in een stad waar Romeinse straten en monumenten nog mee bepaalden welke ruimte beschikbaar was.']],
    'Vergelijk publieke bouwprojecten langs de Rhône vóór en na de Romeinse tijd.', ['Welk bewijs kan voortgezet gebruik van een stadsruimte aantonen?', 'Gedateerde aanpassingen aan oude percelen of muren ondersteunen hergebruik. De aanwezigheid van oude stenen alleen verklaart de nieuwe functie niet.'],
    [wh(164,'Arles, Roman and Romanesque Monuments')]),
  site('bordeaux','Bordeaux','Frankrijk · Garonne',[-.572,44.842],'earlymodern',1750,'Burdigala Bordeaux Port de la Lune',
    [[50,390,'Burdigala'],[1400,null,'Bordeaux']],[
      ['Romeinse keizertijd','Burdigala aan de rivier','Burdigala gebruikte de Garonne als toegang tot een groter handelsnetwerk. Het bewaarde amfitheater, het Palais Gallien, toont een andere stedelijke functie dan de overslag van goederen aan de rivier.'],
      ['18e eeuw','De gevel van de haven','De herinrichting van kades en pleinen keerde de bebouwing naar de rivier. Achter de nieuwe gevels lagen Atlantische handelsbetrekkingen, waaronder slavernij en de handel in producten uit plantagekolonies.']],
    'Onderzoek wat de monumentale kades van een Atlantische haven zichtbaar maken over handel en stedelijke macht.', ['Waarom vertelt een gevelrij maar een deel van de geschiedenis van een haven?', 'Zij toont de bestemming van stedelijke investeringen. Scheepsregisters en handelsarchieven zijn nodig om herkomst van goederen en rol van gedwongen arbeid te bepalen.'],
    [wh(1256,'Bordeaux, Port of the Moon'),ref('Musée d’Aquitaine','Collections','Le commerce atlantique et l’esclavage','https://www.musee-aquitaine-bordeaux.fr/')],['atlantische-slavernij']),
  site('tarragona','Tarragona','Spanje · Catalonië',[1.255,41.117],'roman',100,'Tarraco Tarragona Hispania Tarraconensis',
    [[-200,350,'Tarraco']],[
      ['Vanaf de late 3e eeuw v.Chr.','Een Romeins steunpunt','De Romeinse aanwezigheid aan de kust dateert uit de oorlog tegen Carthago. De ligging maakte verbindingen over land en zee mogelijk. Verdedigingsmuren geven aanknopingspunten voor de groei van het stedelijke gebied.'],
      ['1e–2e eeuw n.Chr.','Een provinciale hoofdstad','In het hoger gelegen deel van Tarraco lagen monumentale terrassen voor cultus en vertegenwoordiging. Een circus sloot erop aan. De combinatie laat zien dat provinciaal bestuur ook een publiek en ritueel gezicht had.']],
    'Waarom lagen cultus, bestuur en publieke gebouwen in Tarraco zo dicht bij elkaar?', ['Wat maakt een monumentale tempel bruikbaar voor de studie van provinciaal bestuur?', 'De plaats in een samenhangend complex met vergader- en publieke ruimten toont de institutionele omgeving. Inscripties kunnen de financiers en deelnemers nader identificeren.'],
    [wh(875,'Archaeological Ensemble of Tarraco')],['struct-ro-provincies']),
  site('cartagena','Cartagena','Spanje · Zuidoost-Iberië',[-.985,37.601],'roman',-209,'Qart Hadasht Carthago Nova Cartagena',
    [[-220,-210,'Qart Hadasht'],[-208,250,'Carthago Nova']],[
      ['Late 3e eeuw v.Chr.','Van Punische naar Romeinse haven','De Barcidische machthebbers benutten een beschutte haven aan de Iberische kust. Scipio nam de stad in 209 v.Chr. in. Dezelfde plek kwam zo in een andere militaire en bestuurlijke organisatie terecht.'],
      ['Tijd van Augustus','Een theater in de heuvel','Het Romeinse theater gebruikte de helling voor de tribunes. Latere bebouwing bedekte het complex. De combinatie van inscripties, bouwelementen en vindlagen maakte een reconstructie van zijn bouwgeschiedenis mogelijk.']],
    'Volg één haven van de oorlog om Iberië naar publieke bouw in een Romeinse stad.', ['Waarom moeten de verovering van de haven en de bouw van het theater afzonderlijk worden gedateerd?', 'Tussen de machtswissel van 209 v.Chr. en het Augusteïsche bouwproject verliepen generaties. Het theater toont een latere vorm van publieke investering.'],
    [ref('Polybios','Historiën','10.10–15, inname van de stad','https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Polybius/10*.html'),ref('Región de Murcia','Teatro Romano','Information, Roman theatre of Cartagena','https://www.turismoregiondemurcia.es/en/museum/teatro-romano-349/')],['rome-punische-oorlogen']),
  site('merida','Mérida','Spanje · Guadiana',[-6.344,38.917],'roman',-25,'Emerita Augusta Augusta Emerita Lusitania Merida',
    [[-25,400,'Augusta Emerita']],[
      ['25 v.Chr.','Een kolonie voor veteranen','Augustus stichtte Augusta Emerita aan de Guadiana. De vestiging van afgezwaaide soldaten koppelde de regeling van hun diensttijd aan Romeinse aanspraken op land en bestuur in het westen van het schiereiland.'],
      ['Keizertijd en late oudheid','Een centrum van Lusitania','Brug, waterleiding, theater en circus bedienden verschillende stedelijke behoeften. Ook in de laat-Romeinse reorganisatie behield de stad een bestuurlijke rol. De overblijfselen maken zichtbaar dat provinciaal gezag infrastructuur vergde.']],
    'Hoe hing de vestiging van veteranen samen met de uitbouw van een provinciale hoofdstad?', ['Welke twee soorten infrastructuur verbinden de inwoners met hun omgeving?', 'De brug vergemakkelijkte verkeer over de Guadiana; de waterleiding voerde water van buiten de stad aan. Beide vragen onderhoud en organisatie.'],
    [wh(664,'Archaeological Ensemble of Mérida')]),
  site('cordoba','Córdoba','Spanje · Guadalquivir',[-4.779,37.879],'medieval',950,'Corduba Qurtuba Qurṭuba Córdoba Cordoba',
    [[-100,350,'Corduba'],[800,1235,'Qurṭuba'],[1250,null,'Córdoba']],[
      ['Romeinse keizertijd','Corduba aan de Baetis','Een brug verbond de Romeinse stad met de overzijde van de Guadalquivir. De ligging aan de rivier verklaart haar verbindingen met Baetica. Onderdelen van de huidige brug zijn het resultaat van latere verbouwingen.'],
      ['8e–10e eeuw','De grote moskee','De opeenvolgende Omajjadische uitbreidingen vergrootten de gebedsruimte. Wie zuilenrijen en bouwfasen afzonderlijk bekijkt, kan politieke presentatie én de praktische inrichting van een moskee onderzoeken.'],
      ['13e eeuw en later','Een kathedraal in een oudere gebedsruimte','Na de verovering door Ferdinand III werd de moskee als kathedraal gebruikt. De latere verbouwingen documenteren hoe veranderingen in gezag en eredienst dezelfde ruimte herschikten.']],
    'Welke machtswisselingen zijn af te lezen aan één gebedshuis?', ['Hoe voorkom je dat het huidige gebouw wordt toegeschreven aan één vorst?', 'Koppel de Omajjadische uitbreidingen en de christelijke ingrepen aan afzonderlijke bouwsporen en bronnen. Het huidige complex bevat beide.'],
    [wh(313,'Historic Centre of Cordoba')]),
  site('korinthe','Korinthe','Griekenland · Isthmos',[22.88,37.906],'greek',-146,'Korinthos Corinth Corinthus',
    [[-700,-147,'Korinthos'],[-44,400,'Corinthus']],[
      ['146 v.Chr.','Een polis wordt ontmanteld','Na de Romeinse overwinning verwoestte het leger van Mummius de stad. Wat in de tussenperiode in het gebied gebeurde, vraagt eigen archeologisch onderzoek. Een besluit tegen de polis betekent nog niet dat ieder perceel onbewoond was.'],
      ['44 v.Chr. en later','Een Romeinse kolonie','Caesar gaf opdracht tot de stichting van een kolonie. Latijnse inscripties geven toegang tot haar publieke ambten en schenkers. Hun talrijkheid zegt ook iets over de gewoonte om politieke functies in steen zichtbaar te maken.']],
    'Wat veranderde tussen de ontmanteling van Korinthe en de stichting van een Romeinse kolonie?', ['Waarom volstaat het aantal Latijnse inscripties niet om de bevolking van Korinthe te tellen?', 'Het aantal hangt af van de gewoonte om in steen te schrijven, van de zichtbaarheid van publieke ambten en van welke wijken zijn opgegraven.'],
    [ref('John Harvey Kent','Corinth VIII.3, The Inscriptions 1926–1950 (1966)','II, The Roman Imperial Period, inleiding bij nrs. 50–500','https://www.ascsa.edu.gr/uploads/media/oa_ebooks/oa_corinth/Corinth_VIII_3.pdf')]),
  site('sparta','Sparta','Griekenland · Lakonië',[22.431,37.081],'greek',-500,'Sparte Sparta Lakedaimon Lacedaemon Eurotas',
    [[-700,250,'Sparta']],[
      ['Archaïsche tijd','Offers bij de Eurotas','Bij het heiligdom van Artemis Orthia laten wijgeschenken en bouwresten zien dat rituelen deel uitmaakten van het stedelijke leven. Ze vullen het door buitenstaanders opgetekende beeld van Spartaanse opvoeding aan.'],
      ['Romeinse keizertijd','Een plek voor toeschouwers','Rond de rituele plaats kwam een voorziening voor publiek. De inrichting maakte het mogelijk dat een groter publiek de handelingen zag. Dat is geen reden om de Romeinse vorm zonder meer naar de archaïsche tijd terug te projecteren.']],
    'Onderzoek hoe een ritueel in Sparta veranderde toen ook de positie van toeschouwers veranderde.', ['Waarom mag de Romeinse tribune geen onderdeel van een reconstructie van archaïsch Sparta zijn?', 'De tribune behoort tot een latere bouwfase. Voor de eerdere organisatie van het ritueel zijn oudere lagen en offers relevant.'],
    [ref('Gemeente Sparta','Orthia Artemis Sanctuary','Archaeological Sites & Monuments','https://realsparta.gr/en-us/What-to-do/Archaelogical-Sites-Monuments/Orthia-Artemis-Sanctuary')]),
  site('thebe','Thebe','Griekenland · Boiotië',[23.319,38.32],'greek',-335,'Thebai Thebae Thebes Kadmeia',
    [[-500,-336,'Thebai'],[-315,200,'Thebai']],[
      ['Bronstijd','Een paleis op de Kadmeia','Onder de moderne stad bevinden zich resten van een Myceens paleiscentrum. Zij behoren tot een ander bestuurlijk bestel dan de klassiek-Griekse polis die eeuwen later in Boiotië een leidende rol zou spelen.'],
      ['335 v.Chr.','Geweld en verplaatsing','Alexander liet de stad na een opstand verwoesten. Bronnen beschrijven ook gevangenschap en vlucht. De verhalen over stedelijke verwoesting moeten naast veranderingen in de graven en de bewoning worden gelegd.'],
      ['316/315 v.Chr.','Herstichting','Onder Kassandros werd Thebe hersticht. Bijdragen van andere steden aan de wederopbouw plaatsen de terugkeer van de gemeenschap in de politieke verhoudingen na Alexanders dood.']],
    'Volg de geschiedenis van Thebe via paleisresten, een verwoesting en de organisatie van de wederopbouw.', ['Waarom is een herstichting ook een sociaal proces?', 'Terugkeer van inwoners, deelname van andere steden en vernieuwing van instellingen vragen eigen bewijs naast de reconstructie van gebouwen.'],
    [ref('Archeologisch Museum van Thebe','Permanent exhibition guide','Afdeling 8, Classical period, p. 30','https://www.mthv.gr/media/44703/FINAL_othigos_eng-ISBN_01.pdf'),ref('Diodorus Siculus','Bibliotheca historica','19.53–54, herstichting onder Kassandros','https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Diodorus_Siculus/19C*.html')]),
  site('delphi','Delphi','Griekenland · Parnassos',[22.501,38.482],'greek',-550,'Delphoi Delphi Delfi Pythia',
    [[-650,300,'Delphoi']],[
      ['8e–6e eeuw v.Chr.','Een orakel met een ruim publiek','Het heiligdom van Apollo groeide uit tot een plaats waar gemeenschappen van ver buiten de streek raad zochten. Wijgeschenken geven concreter zicht op bezoekers dan latere verhalen over wat het orakel ooit zou hebben voorspeld.'],
      ['Klassieke tijd','Schatkamers langs de heilige weg','Poleis bouwden hun eigen schatkamers en stelden geschenken tentoon aan een gedeeld publiek. Deelname aan één cultus en rivaliteit tussen schenkers konden zo gelijktijdig in de inrichting van het heiligdom zichtbaar zijn.']],
    'Lees de heilige weg als plaats van religieuze ontmoeting én rivaliteit tussen steden.', ['Waarom bewijst een gezamenlijke cultus geen politieke eensgezindheid?', 'Poleis konden dezelfde Apollo vereren en tegelijk hun eigen overwinningen en prestige tegenover elkaar tentoonstellen.'],
    [wh(393,'Archaeological Site of Delphi')]),
  site('olympia','Olympia','Griekenland · Elis',[21.63,37.638],'greek',-450,'Olympia Altis Zeus',
    [[-700,300,'Olympia']],[
      ['Vroege ijzertijd','Een heiligdom in een riviervallei','Offers aan Zeus vormden een belangrijk onderdeel van de ontwikkeling van Olympia. De datum 776 v.Chr. is de traditionele aanvang van de reeks olympische spelen. Zij dateert niet de eerste cultushandeling op de plaats.'],
      ['Klassieke tijd','Sport, eredienst en zichtbaarheid','Stadion, altaren en tempels organiseerden verschillende activiteiten van hetzelfde festival. Wijgeschenken en overwinningsmonumenten brachten deelnemers en financiers in beeld en konden ook buiten de wedstrijden worden bekeken.']],
    'Plaats de wedstrijden van Olympia in een heiligdom waar ook buiten de spelen mensen kwamen.', ['Wat is het verschil tussen de traditionele datum 776 v.Chr. en de oudste offers?', 'De datum hoort bij de overgeleverde chronologie van de wedstrijden. De ouderdom van cultus wordt met eigen vondsten en lagen onderzocht.'],
    [wh(517,'Archaeological Site of Olympia')]),
  site('efeze','Efeze','Turkije · Kaystros',[27.342,37.94],'greek',125,'Ephesos Ephesus Efes Efeze',
    [[-250,500,'Ephesos']],[
      ['Hellenistische tijd','Een stad aan een bewegende kust','De nederzetting verplaatste zich in de loop van haar geschiedenis. Sediment uit de rivier veranderde de ligging van de kust en de toegang tot open water. Een hedendaagse kaart volstaat daarom niet om de antieke haven te reconstrueren.'],
      ['Romeinse keizertijd','Een haven met een stedelijk publiek','Havenstraat, theater en bibliotheek verbonden de route van aankomst met monumentale gebouwen. De cultus van Artemis trok bezoekers; de monumenten tonen uiteenlopende vormen van publieke en particuliere investering.'],
      ['Late oudheid','Nieuwe pelgrimsroutes','Christelijke cultus en pelgrimage brachten nieuwe bestemmingen in het omliggende landschap. De ontwikkeling van een heilige plaats moet per bouwfase en beschikbare tekst worden nagegaan.']],
    'Hoe veranderden een terugwijkende kust en religieuze bezoekers de ruimte van Efeze?', ['Waarom kan een huidige afstand tot de zee de positie van de Romeinse haven niet bewijzen?', 'De rivier zette sediment af. Oude kades en geologische lagen moeten samen de vroegere kustlijn vastleggen.'],
    [wh(1018,'Ephesus')]),
  site('pergamon','Pergamon','Turkije · Bakırçay',[27.185,39.133],'greek',-180,'Pergamum Pergamos Bergama Attaliden',
    [[-250,350,'Pergamon']],[
      ['3e–2e eeuw v.Chr.','Een dynastie op de heuvel','De Attaliden maakten van de akropolis een vorstelijk centrum. Terrassen, heiligdommen en theater gebruikten het steile terrein om functies te scheiden en vorstelijke investeringen vanaf grote afstand zichtbaar te maken.'],
      ['Romeinse keizertijd','De stad groeit voorbij de akropolis','De Romeinse stad ontwikkelde zich ook lager in het landschap. In het Asklepieion kwamen zieken, bezoekers en religieuze specialisten samen. Heiligdom en hofstad hadden elk een eigen geschiedenis en publiek.']],
    'Vergelijk de akropolis van de Attaliden met het landschap van het Romeinse Asklepieion.', ['Waarom is de akropolis geen volledige kaart van keizerlijk Pergamon?', 'Expansie en cultusplaatsen strekten zich uit tot buiten de oude bovenstad. Alleen de akropolis bekijken overschat de continuïteit van de hellenistische kern.'],
    [wh(1457,'Pergamon and its Multi-Layered Cultural Landscape')]),
  site('milete','Milete','Turkije · Meanderdelta',[27.278,37.53],'greek',-494,'Miletos Miletus Milet Milete',
    [[-550,-495,'Miletos'],[-300,250,'Miletos']],[
      ['494 v.Chr.','Een stad na de Ionische Opstand','Herodotos beschrijft de inname van Milete na de zeeslag bij Lade. Zijn verslag over nederlaag en wegvoering is een verhalende bron. De geordende nieuwbouw uit latere eeuwen vraagt afzonderlijk gedateerde materiële sporen.'],
      ['Hellenistische en Romeinse tijd','Een theater verandert van vorm','Bij de Romeinse verbouwing van het theater kreeg de toneelbouw een monumentale gevel. De opstelling van spelers en publiek veranderde mee. Het gebouw laat zo verschillende opvattingen over optreden en stedelijke representatie zien.']],
    'Scheid de verhalen over de inname van Milete van de sporen van haar latere stedelijke leven.', ['Wat leert de verbouwing van het theater over continuïteit?', 'De plaats bleef een theater, maar de nieuwe toneelbouw veranderde het gebruik en uiterlijk. Functie en concrete uitvoering moeten apart worden vergeleken.'],
    [ref('Herodotos','Historiën','6.18–22, de inname van Milete','https://classics.mit.edu/Herodotus/history.6.vi.html'),ref('Foundation of the Hellenic World','A Walk through Ancient Miletus','The Theatre','https://www.ime.gr/choros/miletus/en/theatro.php?menu_id=9&submenu_id=916')]),
  site('smyrna','Smyrna / İzmir','Turkije · Golf van İzmir',[27.139,38.418],'greek',178,'Smyrne İzmir Izmir Smyrna Pagos Kadifekale',
    [[-250,350,'Smyrna']],[
      ['Hellenistische tijd','Een nieuw stedelijk centrum','De stad rond de heuvel Pagos had een agora met ruimte voor handel, bestuur en ontmoetingen. Het oudere Smyrna bij Bayraklı lag elders. De speld markeert de agora van de latere stad.'],
      ['Na 178 n.Chr.','Wederopbouw na een aardbeving','Na de aardbeving kreeg Smyrna hulp onder Marcus Aurelius. Veel zichtbare delen van de agora stammen uit deze herbouw. Wie een zuilengalerij wil dateren, moet dus onderscheid maken tussen de aanleg van het plein en het huidige muurwerk.']],
    'Lees een herbouwd plein als bron voor plaatselijk herstel en relaties met de keizer.', ['Waarom kunnen plein en zuilen verschillende dateringen hebben?', 'Het plan van de agora bestond al eerder. Na de aardbeving werd de gebouwenrand grotendeels vernieuwd.'],
    [ref('İzmir Provincial Directorate of Culture and Tourism','İzmir Agora','Beschrijving van plaats en Romeinse herbouw','https://izmir.ktb.gov.tr/EN-240781/izmir-agora.html')]),
  site('antiochie','Antiochië aan de Orontes','Turkije · Antakya',[36.16,36.202],'greek',-300,'Antiocheia Antiochia Antioch Antakya Orontes',
    [[-300,450,'Antiocheia']],[
      ['Ca. 300 v.Chr.','Een Seleucidische stichting','Seleukos I stichtte Antiochië aan de Orontes. De rivier en de nabijgelegen kust verbonden de residentie met andere delen van het rijk. De naam komt vaker voor in Seleucidisch gebied; de rivier identificeert deze stad.'],
      ['Romeinse keizertijd','Een grootstad aan een oostelijke grens','Als centrum van Romeins Syrië bleef de stad verbonden met verkeer tussen de Middellandse Zee en het binnenland. Wisselend militair gezag en christelijke gemeenschappen voegden nieuwe functies toe aan de oudere residentiestad.']],
    'Waarom werd een hellenistische residentie ook onder Rome een belangrijk stedelijk knooppunt?', ['Welke aanwijzingen maken deze plaats herkenbaar tussen andere steden met de naam Antiochië?', 'De ligging aan de Orontes en de verbinding met de kust onderscheiden de stad van andere Seleucidische stichtingen.'],
    [ref('Encyclopaedia Iranica','Antioch (1), Northern Syria','Ancient period','https://www.iranicaonline.org/articles/antioch-1-northern-syria/')]),
  site('carthago','Carthago','Tunesië · Golf van Tunis',[10.324,36.853],'roman',-146,'Qart Hadasht Carthage Karthago Carthago',
    [[-650,-147,'Qart Hadasht'],[-15,650,'Carthago']],[
      ['1e millennium v.Chr.','Een Punische stad met maritieme netwerken','Aan de Golf van Tunis verbonden havens de stad met nederzettingen en handelsroutes rond de Middellandse Zee. Havens, graven en religieuze monumenten leveren onafhankelijk bewijs naast Romeinse teksten over een tegenstander.'],
      ['146 v.Chr.','Verwoesting','De Derde Punische Oorlog eindigde met de inname en verwoesting van de stad. De breuk maakt het nodig om gebouwen op Byrsa en rond de havens eerst aan een fase toe te wijzen voordat men ze als bewijs gebruikt.'],
      ['Romeinse keizertijd en late oudheid','Een andere stad op dezelfde plek','De herstichte Romeinse stad kreeg onder meer thermen en een wateraanvoer. Later zetelden er Vandaalse en Oost-Romeinse machthebbers. Het voortbestaan van een plaatsnaam verbergt zulke veranderingen in bestuurscentrum en cultus.']],
    'Hoe herken je de overgang van Punisch handelscentrum naar Romeinse provinciale stad?', ['Waarom kun je de Antonijnse thermen niet gebruiken voor Hannibals stadsbeeld?', 'De thermen behoren tot de Romeinse stad na de herstichting. Voor Hannibals tijd zijn de Punische bouwlagen en contemporaine vondsten relevant.'],
    [wh(37,'Archaeological Site of Carthage')],['rome-punische-oorlogen']),
  site('aphrodisias','Aphrodisias','Turkije · Karië',[28.724,37.709],'roman',125,'Aphrodisias Afrodisias Geyre Karie Caria',
    [[-50,450,'Aphrodisias']],[
      ['Late republiek en keizertijd','Een heiligdom en een polis','De verering van Aphrodite gaf de stad een bijzonder verband met Romeinse machthebbers. Het marmer uit de omgeving werd gebruikt voor standbeelden en openbare gebouwen. De financiering van die projecten moest telkens opnieuw worden geregeld.'],
      ['2e eeuw n.Chr.','Spektakel, kosten en een keizerlijke brief','Een brief van Hadrianus bespreekt een aquaduct en de lasten rond het hogepriesterschap. De tekst vermeldt de wensen van de stad en het antwoord van de keizer. Daarmee documenteert hij een onderhandeling, zonder alle betalingen of de uitkomst van het bouwproject te bewijzen.'],
      ['Late oudheid','De tempel wordt een kerk','Bij de ombouw van de Aphroditetempel wijzigden de bouwers de oriëntatie en de inrichting van de ruimte. De zichtbare stenen dragen daardoor zowel sporen van de vroegere cultus als van een christelijke gemeenschap.']],
    'Verbind de inscriptie over stedelijke uitgaven met de stenen monumenten van een Griekse polis onder Rome.', ['Welke vraag kun je met een keizerlijke brief beter beantwoorden dan met het stadion alleen?', 'De brief geeft toegang tot de voorgelegde prioriteiten en de reactie van Hadrianus. Het stadion toont fysieke mogelijkheden, maar geen onderhandelingen over een specifieke uitgave.'],
    [wh(1519,'Aphrodisias'),ref('Joyce Reynolds','Letters of Hadrian to Aphrodisias on trials, taxes and an aqueduct (2000)','JRA 13, pp. 5–20, brief III, rr. 27–41','https://droitromain.univ-grenoble-alpes.fr/Constitutiones/Aphrodisienses8.gr.html'),ref('Kathleen M. Coleman','Exchanging Gladiators for an Aqueduct at Aphrodisias (2008)','Acta Classica 51, pp. 31–46, vooral pp. 31–32','https://casa-kvsa.org.za/legacy/2008/AC51-04-Coleman.pdf')]),
  site('brugge','Brugge','België · Vlaanderen',[3.224,51.209],'medieval',1350,'Bruges Brugge Zwin',
    [[1150,null,'Brugge']],[
      ['Hoge en late middeleeuwen','Handel rond een binnenhaven','Waterwegen verbonden Brugge via voorhavens met de Noordzee. Buitenlandse kooplieden en lokale makelaars maakten de stad tot een ontmoetingsplaats. De ligging alleen verklaart de handel niet; ook krediet, opslag en bemiddeling waren nodig.'],
      ['15e eeuw','Een stad van hof, kunst en ambacht','De aanwezigheid van het Bourgondische hof en kapitaalkrachtige stedelingen schiep opdrachten voor kunstenaars en ambachtslieden. Schilderijen tonen hun opdrachtgevers selectiever dan bijvoorbeeld handelsrekeningen of belastingregisters.']],
    'Hoe hingen Brugse voorhavens, handelsinstellingen en opdrachtgevers samen?', ['Waarom levert een schilderij van een koopman geen doorsnede van de Brugse bevolking?', 'Een portret vergt middelen en een opdrachtgever. Voor loonarbeiders, migranten en dienstverlening zijn andere bronnen nodig.'],
    [wh(996,'Historic Centre of Brugge')],['struct-me-steden']),
  site('ieper','Ieper','België · Westhoek',[2.886,50.851],'medieval',1300,'Ypres Ieper Ieperlee In Flanders Fields',
    [[1150,null,'Ieper']],[
      ['13e–14e eeuw','Een markt voor lakens','De Lakenhalle verbond opslag, controle en verkoop van laken op de Grote Markt. Het gebouw maakt het economische en politieke gewicht van stedelijke textielproductie zichtbaar. Het thuiswerk van spinners en wevers liet minder monumentale sporen na.'],
      ['1914–1918 en de wederopbouw','Een gereconstrueerd stadsgezicht','Het oorlogsgeweld verwoestte de oude hal. Bij de wederopbouw koos men voor een reconstructie van de historische gevel. Wie nu op de markt staat, ziet tegelijk een middeleeuws ontwerp en twintigste-eeuwse opvattingen over herstel.']],
    'Waarom moet je bij de Ieperse Lakenhalle onderscheid maken tussen bouwvorm en ouderdom van het materiaal?', ['Welke twee geschiedenissen kun je met de huidige Lakenhalle bestuderen?', 'Het oude ontwerp verwijst naar de stedelijke lakenhandel. Het herbouwde materiaal documenteert de keuzes na de oorlog.'],
    [ref('Stad Ieper','Gemeentelijk ruimtelijk structuurplan, informatief gedeelte','p. 82, Stedelijk Ieper','https://www.ieper.be/ntegrale-versie')],['eerste-wereldoorlog']),
  site('kortrijk','Kortrijk','België · Leie',[3.269,50.828],'medieval',1302,'Courtrai Kortrijk Groeningekouter',
    [[1250,null,'Kortrijk']],[
      ['11 juli 1302','Een veldslag buiten de stad','Op de Groeningekouter versloeg een leger uit het graafschap Vlaanderen het koninklijke leger van Filips IV. De strijd ontstond uit conflicten over gezag in het graafschap, stedelijke tegenstellingen en de verhouding met de Franse kroon.'],
      ['Latere herinnering','Een veldslag krijgt nieuwe betekenissen','De strijd werd in monumenten, herdenkingen en tentoonstellingen telkens opnieuw verteld. Een moderne maquette of een nationaal verhaal documenteert de interpretatie van 1302 en heeft een andere bewijskracht dan een contemporaine kroniek.']],
    'Leg het conflict in het graafschap Vlaanderen naast de latere herdenking van de slag.', ['Welke vraag beantwoord je met een recent monument beter dan met een kroniek?', 'Een monument laat zien wie de slag later herdacht en welke betekenis zij eraan gaven. Voor het verloop van de strijd zijn vroegere bronnen nodig.'],
    [ref('Visit Kortrijk','1302. Opstand, slag, keerpunt','Museumparcours en belevingstafel over de slag','https://www.visitkortrijk.be/nl/1302')]),
  site('londen','Londen','Verenigd Koninkrijk · Theems',[-.087,51.511],'roman',100,'London Londinium Theems Thames',
    [[55,400,'Londinium'],[1100,null,'London']],[
      ['Ca. 50–60 n.Chr.','Een haven aan de Theems','De Romeinse nederzetting groeide bij een oversteek van de rivier. Straten, kades en goederen verbonden militairen, handelaars en ambachtslieden. In veel opgravingen bewaart de natte bodem ook houten constructies.'],
      ['60/61 n.Chr. en later','Vernieling en herbouw','Tijdens de opstand van Boudica werd Londinium verwoest. Brandlagen en de heraanleg van straten geven een ander soort bewijs dan Romeinse verslagen. De stad kon zich vervolgens opnieuw ontwikkelen als haven en bestuurlijk centrum.']],
    'Wat vertelt de herbouw van Londinium na de opstand van Boudica?', ['Hoe toets je een geschreven bericht over de verwoesting van een stad?', 'Vergelijk gedateerde brandlagen en de ligging van bebouwing vóór en na de brand. Zo kun je ook onderscheiden welke delen bij één onderzoek zichtbaar werden.'],
    [ref('London Museum','A timeline of Roman London: Londinium from start to end','The early years en Boudica’s revolt','https://www.londonmuseum.org.uk/collections/london-stories/timeline-roman-london-londinium/')]),
  site('oxford','Oxford','Verenigd Koninkrijk · Theems',[-1.255,51.754],'medieval',1167,'Oxonia Oxford university universiteit',
    [[1096,null,'Oxford']],[
      ['1096','Onderwijs zonder stichtingsakte','Voor dit jaar is onderwijs in Oxford aantoonbaar. Er is geen enkele bekende stichtingsdatum voor de universiteit. Aanwijzingen voor lesgeven en bewijs voor een georganiseerde universitaire instelling beantwoorden verschillende vragen.'],
      ['Vanaf 1167','Geleerden en instellingen','De terugkeer van Engelse studenten nadat Hendrik II studie in Parijs beperkte, gaf Oxford een impuls. Colleges, voorzieningen en regels groeiden geleidelijk. Studentenpopulatie en de rechtspersoon van een college moeten daarom afzonderlijk worden gedateerd.']],
    'Hoe onderzoek je het ontstaan van een universiteit zonder eenduidig stichtingsjaar?', ['Is 1096 een bewezen stichtingsdatum voor de universiteit?', 'De bron levert bewijs van onderwijs in dat jaar. Voor formele rechten, bestuur en colleges moet je andere en vaak latere documenten raadplegen.'],
    [ref('University of Oxford','Our history','The early days','https://www.ox.ac.uk/about/the-university/history')],['struct-me-steden']),
  site('venetie','Venetië','Italië · Lagune',[12.339,45.435],'medieval',1200,'Venezia Venice Venise Venetia',
    [[1000,null,'Venezia']],[
      ['Vanaf de 5e eeuw','Wonen tussen land en water','Bewoning op verschillende lagune-eilanden ging vooraf aan de concentratie rond het latere stadscentrum. Vaarwegen verbonden de eilanden. De vroege geschiedenis van de lagune is daarom ruimer dan die van het huidige San Marcoplein.'],
      ['Middeleeuwen','Scheepvaart en stedelijke macht','De republiek gebruikte handelscontacten, havens en scheepsbouw om haar invloed uit te breiden. Het Arsenaal toont de schaal waarop arbeid en materialen konden worden georganiseerd, terwijl koopmansarchieven afzonderlijke transacties beter laten volgen.']],
    'Volg de overgang van verspreide eilandbewoning naar een stad met een grote scheepsbouwnijverheid.', ['Waarom vormt één eiland geen afdoende verklaring voor de groei van Venetië?', 'Vervoer, scheepsbouw, bevoorrading en vroege bewoning waren over de lagune en verdere vaarroutes verdeeld.'],
    [wh(394,'Venice and its Lagoon')]),
  site('florence','Florence','Italië · Toscane',[11.254,43.772],'earlymodern',1450,'Firenze Florentia Florence Arno',
    [[-30,350,'Florentia'],[1200,null,'Firenze']],[
      ['Romeinse tijd','Florentia aan de Arno','De Romeinse kolonie nam een plaats in aan de Arno. Het regelmatige stratenplan rond de oude kern kan met resten onder latere gebouwen worden vergeleken. De zichtbaarheid van dat patroon bewijst geen onveranderde omvang van de stad.'],
      ['14e–16e eeuw','Ambacht, politiek en kunst','De groei van het stedelijke vermogen schiep opdrachten voor grote kerkelijke en publieke bouwprojecten. Onder de Medici werd patronage een middel van politieke profilering. Gilden, kerkelijke instellingen en andere families bleven eveneens opdrachtgevers.']],
    'Wat leert het Florentijnse stadsbeeld over de verschillende opdrachtgevers van renaissancekunst?', ['Waarom moet je patronage per bouwproject onderzoeken?', 'Gilden, kerkelijke instellingen en de Medici hadden verschillende middelen en belangen. Een stijl of een stadsnaam identificeert de opdrachtgever niet.'],
    [wh(174,'Historic Centre of Florence')]),
  site('keulen','Keulen','Duitsland · Rijn',[6.959,50.941],'roman',50,'Köln Cologne CCAA Colonia Claudia Ara Agrippinensium',
    [[50,380,'Colonia Claudia Ara Agrippinensium'],[1250,null,'Köln']],[
      ['50 n.Chr.','Een kolonie aan de Rijn','Onder Claudius kreeg de nederzetting de titel van Romeinse kolonie. De uitgebreide stadsnaam verwees ook naar Agrippina. Een juridische statusverandering is daarmee beter te dateren dan het begin van alle bewoning op de plek.'],
      ['Middeleeuwen en 19e eeuw','Een kathedraal over eeuwen','De gotische dom werd in de dertiende eeuw begonnen en in de negentiende voltooid. Zijn ogenschijnlijk eenvormige buitenkant vraagt onderzoek naar twee verschillende contexten van patronage, financiering en historische belangstelling.']],
    'Plaats een Romeinse kolonietitel en een eeuwenlang kerkelijk bouwproject elk in hun tijd.', ['Waarom is het verleend koloniale stadsrecht geen bewijs voor de eerste bewoning?', 'De titel veranderde de juridische positie van een bestaande nederzetting. Oudere bewoningsresten moeten onafhankelijk worden gedateerd.'],
    [ref('Museen der Stadt Köln','Metropolis on the Rhine','Legacy of the Romans, kolonietitel en Agrippina','https://downloads.museenkoeln.de/home/ITBBroschuere_EN.pdf'),wh(292,'Cologne Cathedral')]),
  site('aken','Aken','Duitsland · Rijnland',[6.084,50.775],'medieval',800,'Aachen Aix-la-Chapelle Aquisgranum',
    [[795,1000,'Aquisgranum'],[1200,null,'Aachen']],[
      ['Rond 790–800','Een kapel voor het hof','Karel de Grote liet een paleiskapel met een centrale achthoek bouwen. Het gebouw bood ruimte aan de liturgie van het hof. Architectonische verwijzingen naar oudere vorstelijke kerken hielpen zijn gezag voor een publiek herkenbaar te maken.'],
      ['Middeleeuwen','Een plaats van kroning en herinnering','Latere vorsten gebruikten Aken voor kroningen. Door toevoegingen aan kapel en koor veranderde de loop van bezoekers en geestelijken. Hetzelfde gebouw droeg zo uiteenlopende politieke en religieuze herinneringen.']],
    'Hoe werd een Karolingische hofkapel een latere plaats van kroning en herinnering?', ['Welk bewijs is nodig om een kroning in Aken te dateren?', 'De kapel toont een mogelijke omgeving. Vermeldingen in gedateerde teksten of handelingen zijn nodig om een concrete ceremonie en deelnemer te identificeren.'],
    [wh(3,'Aachen Cathedral')],['h2-karolingische-schriftcultuur']),
  site('wenen','Wenen','Oostenrijk · Donau',[16.372,48.21],'history',1860,'Vindobona Wien Vienna Ringstraße',
    [[100,350,'Vindobona'],[1250,null,'Wien']],[
      ['Romeinse keizertijd','Een legerplaats aan de Donau','Vindobona maakte deel uit van de Romeinse aanwezigheid langs de rivier. De militaire nederzetting en de civiele omgeving vervulden verschillende functies. Onder het latere stadscentrum zijn resten van het legerkamp teruggevonden.'],
      ['19e eeuw','Van verdedigingsgordel tot Ringstraße','Na de beslissing om de omwalling op te heffen kwam er een boulevard met publieke gebouwen. Het tracé maakte zichtbaar hoe de vroegere scheiding tussen binnenstad en voorsteden voor vervoer en representatie werd hergebruikt.']],
    'Welke stedelijke grenzen zijn ook na afbraak nog in het stratenplan terug te vinden?', ['Waarom kun je de Ringstraße niet zonder meer als een Romeins kamptracé lezen?', 'De boulevard volgt de veel latere verdedigingsgordel. Voor het Romeinse kamp zijn de archeologische resten in de binnenstad bepalend.'],
    [wh(1033,'Historic Centre of Vienna')]),
  site('praag','Praag','Tsjechië · Moldau',[14.421,50.088],'medieval',1350,'Praha Prague Praag Vltava Karelsbrug',
    [[1100,null,'Praha']],[
      ['Middeleeuwen','Een groep stedelijke kernen','Burcht, wijken en markten aan weerszijden van de Moldau ontwikkelden zich niet allemaal op hetzelfde moment. Wie middeleeuws Praag reconstrueert, moet rekening houden met de verbindingen en rechten van verschillende stadsdelen.'],
      ['14e eeuw','De ingrepen van Karel IV','Onder Karel IV kregen nieuwe stadsaanleg, brug en kathedraal bijzondere steun. De Karelsbrug verbond beide oevers terwijl religieuze en politieke gebouwen de positie van de residentie in het rijk zichtbaar maakten.']],
    'Onderzoek hoe een nieuwe brug het gebruik van oudere stedelijke kernen veranderde.', ['Welke bron heb je naast een brugplan nodig om gebruikers van de brug te kennen?', 'Tolregisters, stedelijke gegevens of beschrijvingen geven informatie over verkeer en groepen. De vorm van de brug toont vooral de mogelijke route.'],
    [wh(616,'Historic Centre of Prague')]),
  site('granada','Granada','Spanje · Andalusië',[-3.59,37.176],'medieval',1350,'Gharnata Garnata Granada Alhambra Nasriden',
    [[1250,1491,'Gharnāṭa'],[1493,null,'Granada']],[
      ['13e–15e eeuw','Een Nasridisch hof','Het Alhambra combineerde versterking, paleis en werkruimten. De Generalife bood een eigen buitenverblijf met tuinen. In de Albaicín aan de andere zijde lagen woningen en straten met een andere relatie tot het hof.'],
      ['Na 1492','Hergebruik na de verovering','Na de overgave van Granada nam de christelijke monarchie de paleisomgeving in gebruik. Latere ingrepen, waaronder het paleis van Karel V, voegden een andere vorstelijke vormentaal toe aan de bestaande gebouwen.']],
    'Vergelijk de ruimten van het Nasridische hof met de ingrepen na de overgave van Granada.', ['Waarom moet een reconstructie van de Nasridische hoofdstad ook de Albaicín tonen?', 'Het paleiscomplex vertegenwoordigt vooral het hof. Wijken aan de overzijde maken het verschil tussen residentie en bredere stedelijke leefruimte zichtbaar.'],
    [wh(314,'Alhambra, Generalife and Albayzín, Granada')]),
  site('groot-zimbabwe', 'Groot-Zimbabwe', 'Zimbabwe · Hoogvlakte bij Masvingo', [30.934, -20.268], 'medieval', 1350, 'Great Zimbabwe Shona Masvingo',
    [[1100, 1450, 'Groot-Zimbabwe (vindplaats)']], [
      ['11e–15e eeuw', 'Wonen tussen granieten heuvels', 'Bewoningslagen op de heuvel getuigen van opeenvolgende huishoudens. Smalle doorgangen en stenen omheiningen stuurden wie een ruimte kon binnengaan. De identificatie van bepaalde zones als residentie of cultusplaats steunt op de combinatie van inrichting en vondsten.'],
      ['14e eeuw', 'Een omheining in de vlakte', 'Ten zuiden van de heuvel bouwden steenhouwers een grote omheining van zorgvuldig gestapelde granietblokken. Binnen de muren lagen ook woningen in aarde. Het verschil in bewaring tussen stevige buitenmuren en kwetsbare woonvloeren bepaalt in sterke mate ons huidige beeld van de stad.']],
    'Hoe reconstrueer je de leefruimte achter een monumentale buitenmuur?', ['Welke onderdelen ontsnappen wanneer je alleen de granieten muren documenteert?', 'Woningen in aarde, keukens, vloeren en gebruiksvoorwerpen leveren juist bewijs voor huishoudens en activiteiten binnen de omheining.'],
    [wh(364, 'Great Zimbabwe National Monument')]),
  site('aksum', 'Aksum', 'Ethiopië · Noordelijke hooglanden', [38.719, 14.131], 'history', 350, 'Axum Aksum Adulis Ezana Geëz',
    [[200, 700, 'Aksum']], [
      ['3e–4e eeuw', 'Stèles en graven', 'Grote monolieten markeerden een grafzone. In sommige zijn verdiepingen en deuren van gebouwen nagebootst. Dit toont een keuze in de manier waarop de doden werden herdacht. Voor contact met de Rode Zee moet je daarnaast de routes van het hoogland naar de haven van Adulis volgen.'],
      ['4e eeuw', 'Koninklijke inscripties', 'Van Ezana bleven inscripties in verschillende talen bewaard. Grieks, Geëz en Zuid-Arabische schrifttradities tonen hoe het hof zich aan uiteenlopende lezers voorstelde. De taal van een koninklijk opschrift is een gegeven over de opdrachtgever en zijn publiek, niet over de thuistaal van elke inwoner.']],
    'Wat voegen inscripties toe aan de grafmonumenten van Aksum?', ['Kun je uit een Griekse koningsinscriptie afleiden welke taal ieder huishouden sprak?', 'De taalkeuze toont tot wie het hof zich kon richten. Dagelijks taalgebruik vraagt bewijs uit andere sociale contexten.'],
    [wh(15, 'Aksum')]),
  site('cahokia', 'Cahokia', 'Verenigde Staten · Mississippivallei', [-90.062, 38.657], 'medieval', 1100, 'Cahokia Monks Mound Illinois Mississippi',
    [[1050, 1300, 'Cahokia (vindplaats)']], [
      ['Ca. 1050–1150', 'Landbouw en stedelijke concentratie', 'Op de oostelijke oevervlakte van de Mississippi groeide een grote nederzetting met woonbuurten, pleinen en aarden platforms. Om veel mensen en gespecialiseerde activiteiten op één plek te onderhouden, waren verbindingen met akkers en nederzettingen rondom de stad nodig.'],
      ['Opeenvolgende bouwfasen', 'Monks Mound als bouwwerk', 'Het grootste platform ontstond in opeenvolgende aanlegfasen. Het vroeg herhaald werk om aarde te verzamelen, te verplaatsen en het oppervlak opnieuw aan te leggen. Andere heuvels hadden een andere functie, zoals begraving. Hun aantal op zichzelf geeft dus geen bevolkingstelling.']],
    'Onderzoek wat de bouw van een aarden platform over gezamenlijke arbeid laat zien.', ['Waarom is één grote aarden heuvel geen momentopname van de arbeidskracht?', 'Opeenvolgende bouwlagen kunnen van verschillende projecten en generaties dateren. Hun gezamenlijke volume mag niet als werk van één seizoen worden geteld.'],
    [wh(198, 'Cahokia Mounds State Historic Site')]),
  site('chan-chan', 'Chan Chan', 'Peru · Noordelijke kustvlakte', [-79.075, -8.11], 'medieval', 1400, 'Chimú Chimu Trujillo Chan Chan',
    [[1200, 1450, 'Chan Chan (vindplaats)']], [
      ['Chimú-periode', 'Wonen en werken op de kustvlakte', 'Aan de droge kust kon het stedelijke centrum alleen functioneren met aanvoer uit het omliggende land. Kanalen leidden rivierwater naar de landbouwgebieden. Werkplaatsen, opslag en ceremoniële doorgangen verdelen de gebouwde stad in plaatsen waar mensen verschillende taken uitvoerden.'],
      ['15e eeuw', 'Paleiscomplexen en verovering', 'Aan het eind van de Chimú-periode lagen verschillende ommuurde complexen in de stad. Besloten doorgangen en grote binnenplaatsen tonen hoe toegang kon worden geregeld. De Inka-verovering veranderde de politieke omgeving. Een plattegrond bewijst op zichzelf niet wanneer de laatste ambachtsman een wijk verliet.']],
    'Hoe hangen toegang tot land, water en afzonderlijke stadsdelen samen?', ['Wat heb je naast het plan van de paleizen nodig om de stedelijke voedselvoorziening te reconstrueren?', 'Onderzoek het irrigatiestelsel en de landbouwgronden buiten de muren. Opslagruimten binnen de stad kunnen helpen om de verdere verdeling te volgen.'],
    [wh(366, 'Chan Chan Archaeological Zone')]),
  site('nan-madol', 'Nan Madol', 'Micronesië · Pohnpei', [158.332, 6.845], 'medieval', 1350, 'Pohnpei Saudeleur Nan Madol',
    [[1250, 1450, 'Nan Madol (vindplaats)']], [
      ['Ca. 1200–1500', 'Een centrum gebouwd op eilandjes', 'Aan de kust van Pohnpei werden eilandjes aangelegd met koraal en basalt. Lange basaltblokken moesten van elders op het eiland worden aangevoerd. Het vervoer en de bouwtechniek geven directere aanwijzingen voor georganiseerde arbeid dan een algemene schatting van vorstelijke macht.'],
      ['De Saudeleur en de verdere overlevering', 'Ruimte voor ritueel en gezag', 'Op de eilandjes lagen woonplaatsen, grafmonumenten en ceremoniële gebouwen van het Saudeleur-centrum. Plaatselijke tradities verbinden de plek nog steeds met gezag en ritueel. Om te bepalen wanneer een afzonderlijke constructie ontstond, moet mondelinge overlevering samen met bouwfasen en dateringen worden onderzocht.']],
    'Wat vertelt het vervoer van basalt over samenwerking tussen verschillende plaatsen?', ['Waarom zijn de steengroeven eveneens onderdeel van de geschiedenis van Nan Madol?', 'Het gesteente werd buiten het complex gewonnen. De route tussen groeven en eilandjes maakt arbeid en transport zichtbaar die op een plattegrond van het centrum ontbreken.'],
    [wh(1503, 'Nan Madol: Ceremonial Centre of Eastern Micronesia')]),
  site('angkor', 'Angkor', 'Cambodja · Siem Reap', [103.867, 13.413], 'medieval', 1150, 'Khmer Yasodharapura Angkor Wat Angkor Thom Bayon',
    [[1000, 1400, 'Angkor (archeologisch gebied)']], [
      ['9e–15e eeuw', 'Opeenvolgende hoofdsteden', 'In de huidige regio Angkor legden Khmer-vorsten verschillende stedelijke centra aan. Tempels, wegen, dijken en reservoirs maken hun ruimtelijke verhouding zichtbaar. Angkor Wat en de Bayon in Angkor Thom behoren tot verschillende projecten. Een kaart die beide monumenten toont, voegt dus bouwfasen samen.'],
      ['Na de hoofstedelijke periode', 'Het landschap blijft bewoond', 'Binnen het archeologische gebied wonen en werken ook nu mensen die het landbouwlandschap gebruiken. Het einde van de functie als rijkshoofdstad vormt daarom geen datering voor het verdwijnen van iedere nederzetting of religieuze praktijk. Voor een afzonderlijk kanaal moet men uitzoeken welke aanpassing bij welke fase hoorde.']],
    'Waarom vraagt een geschiedenis van Angkor meer dan een bezoek aan Angkor Wat?', ['Welk onderzoek maakt zichtbaar dat de huidige site verschillende steden en bouwfasen omvat?', 'Dateer de afzonderlijke tempels, stedelijke plannen en waterwerken en breng hun ruimtelijke aansluitingen in kaart.'],
    [wh(668, 'Angkor')]),
  site('mohenjo-daro', 'Mohenjo-daro', 'Pakistan · Benedenloop van de Indus', [68.139, 27.329], 'history', -2400, 'Moenjodaro Harappa Indus Sindh',
    [[-2450, -2100, 'Mohenjo-daro (vindplaats)']], [
      ['3e millennium v.Chr.', 'Water in een Indusstad', 'Huizen, waterputten en afvoerleidingen maken het mogelijk de omgang met water per straat te volgen. Een ordening van doorgaande wegen en zijstraten vergde afspraken tussen bewoners en bouwers. Welke instelling die afspraken maakte, valt minder gemakkelijk uit de bakstenen alleen af te leiden.'],
      ['2e eeuw n.Chr. en opgravingen vanaf 1922', 'Een latere heuvel boven een vroegere stad', 'Op een hoger deel van het terrein verrees eeuwen na de Indusstad een boeddhistische stoepa. Onderzoekers groeven de oudere nederzetting in de twintigste eeuw op. Dezelfde coördinaten verbinden beide perioden, maar hun religieuze en politieke instellingen hoorden bij verschillende gemeenschappen.']],
    'Hoe onderscheid je verschillende gebruiksfasen op dezelfde heuvel?', ['Kan de boeddhistische stoepa de godsdienst van de bouwers van de Indusstad aantonen?', 'De stoepa behoort tot een veel latere bouwfase. Leg de stad en de stoepa apart in de tijd en zoek het bewijs voor hun gebruik in hun eigen lagen.'],
    [wh(138, 'Archaeological Ruins at Moenjodaro')], ['h2-indus-steden']),
  site('my-son', 'Mỹ Sơn', 'Vietnam · Thu Bồn-vallei', [108.122, 15.774], 'medieval', 950, 'My Son Champa Cham Shiva',
    [[750, 1200, 'Mỹ Sơn (heiligdom)']], [
      ['4e–13e eeuw', 'Een koninklijk heiligdom in een vallei', 'Heersers van Champa verbonden een cultus van Shiva met koninklijke patronage. Groepen bakstenen torens verrezen op een afgebakende plaats in de vallei. De gebouwen wijzen op lokale opdrachtgevers en werkwijzen binnen een religieuze wereld die ook ver buiten de regio bestond.'],
      ['Opeenvolgende bouwfasen', 'Een traditie verandert van vorm', 'De bewaarde bouwwerken vertonen verschillende stijlen. Voor onderzoek naar religieus gebruik is het van belang de bouwfasen, grondplannen en afzonderlijke beelden in hun eigen context te plaatsen. Een stilistische gelijkenis met een elders gebouwd heiligdom blijft een aanwijzing die nadere datering en vergelijking vraagt.']],
    'Hoe onderzoek je religieuze contacten zonder de lokale bouwgeschiedenis uit het oog te verliezen?', ['Wat kan een overeenkomst in tempelvorm precies onderbouwen?', 'Een verwante vorm rechtvaardigt vergelijking. Voor contact en overdracht zijn ook datering, opdrachtgevers en de regionale verspreiding van typen en inscripties nodig.'],
    [wh(949, 'My Son Sanctuary')]),
];

